    name: 'Frost Lantern',
    desc: 'Unlock frost lanterns: chill wisps nearby',
    max: 3,
    apply: (u) => { u.frost = (u.frost || 0) + 1; },
  },
  {
    id: 'lantern-slot',
    name: 'Lantern Slot',
