// campaign.js — the campaign of three nights: meta-progression between runs.
//
// One run of LANTERNWARD is a single night of ten waves. A campaign is
// three nights in a row, each with its own objective and its own boss.
// Between nights the keeper stands on the campaign map and spends Dawn
// Shards — earned from beacon rings, the night's objective and the boss —
// on permanent upgrades that carry into every later night: a heart, a
// lantern slot, or the Sun Lantern itself. Draft upgrades carry over too,
// lanterns on the field do not, and half the embers carry to the next
// night. So the build grows across the campaign, and every night starts
// stronger than the last — while the nights themselves get harder.
//
// Pure data and pure functions of (campaign, world) only: no DOM, no RNG,
// no clock. The map screen, the shots and the probes all read this file.

export const NIGHTS = [
  {
    id: 1,
    name: 'FIRST LIGHT',
    short: 'Light the rings',
    objective: { kind: 'rings', target: 5, label: 'Light all 5 beacon rings' },
    boss: { name: 'THE GLOOM HERALD', hp: 26, spawn: 'drifter' },
  },
  {
    id: 2,
    name: 'THE LONG DARK',
    short: 'Banish the horde',
    objective: { kind: 'banishes', target: 40, label: 'Banish 40 wisps' },
    boss: { name: 'THE HOLLOW KING', hp: 32, spawn: 'chaser' },
  },
  {
    id: 3,
    name: "DAWN'S EDGE",
    short: 'Gather the dawn',
    objective: { kind: 'motes', target: 120, label: 'Gather 120 motes' },
    boss: { name: 'THE NIGHT ITSELF', hp: 40, spawn: 'splitter' },
  },
];

// The meta shop on the campaign map: permanent upgrades, bought with
// Dawn Shards. Each may be taken up to `max` times across the campaign.
export const META_SHOP = [
  {
    id: 'ember-heart',
    name: 'Ember Heart',
    desc: '+1 max heart, every night',
    cost: 4,
    max: 2,
    apply: (meta) => {
      meta.hearts += 1;
    },
  },
  {
    id: 'lantern-rack',
    name: 'Lantern Rack',
    desc: '+1 lantern slot, every night',
    cost: 5,
    max: 2,
    apply: (meta) => {
      meta.slots += 1;
    },
  },
  {
    id: 'sun-lantern',
    name: 'Sun Lantern',
    desc: 'Unlock sun lanterns: 3-bolt spread',
    cost: 6,
    max: 1,
    apply: (meta) => {
      meta.sun += 1;
